import java.time.*;
import java.time.format.*;
import java.util.*;

public class Main {
    private final Scanner entrada=new Scanner(System.in);
    private final SistemaEscolar sistema=new SistemaEscolar();
    private static final DateTimeFormatter DATA=DateTimeFormatter.ofPattern("dd/MM/uuuu").withResolverStyle(ResolverStyle.STRICT);
    private static final DateTimeFormatter HORARIO=DateTimeFormatter.ofPattern("dd/MM/uuuu HH:mm").withResolverStyle(ResolverStyle.STRICT);
    public static void main(String[] args){new Main().executar();}
    private void executar(){
        System.out.println("=== GESTAO ESCOLAR | SPRINT 3 ===");
        try{while(true){System.out.println("\nEscolha uma conta de demonstracao (sem senha):");sistema.getUsuarios().forEach(System.out::println);System.out.println("0 - Sair");int id=numero("Conta: ");if(id==0)break;try{Usuario u=sistema.usuario(id);if(u.isProfessor())professor(u);else aluno(u);}catch(IllegalArgumentException e){erro(e);}}}catch(NoSuchElementException e){System.out.println("\nEntrada encerrada.");}finally{entrada.close();}System.out.println("Sistema encerrado.");
    }
    private void professor(Usuario u){while(true){System.out.println("\n--- PROFESSOR: "+u.getNome()+" ---\n1 - Publicar atividade\n2 - Consultar atividades e entregas\n3 - Projetos que oriento\n4 - Ingressar em projeto sem mentor\n5 - Consultar mentorias\n6 - Agendar mentoria\n7 - Responder solicitacao de mentoria\n0 - Trocar conta");try{switch(numero("Opcao: ")){case 0:return;case 1:{Atividade a=sistema.cadastrarAtividade(u,texto("Titulo: "),texto("Materia: "),texto("Descricao: "),data());System.out.println("Atividade cadastrada. ID: "+a.getId());break;}case 2:listarAtividades(u);break;case 3:listarProjetos(sistema.projetosDe(u));break;case 4:if(listarProjetos(sistema.projetosSemMentor(u))){int id=numero("ID projeto (0 cancela): ");if(id!=0){sistema.orientar(u,sistema.projeto(id));System.out.println("Mentor vinculado.");}}break;case 5:listarMentorias(u);break;case 6:if(listarProjetos(sistema.projetosDe(u))){int id=numero("ID projeto (0 cancela): ");if(id!=0){sistema.agendarMentoria(u,sistema.projeto(id),texto("Assunto: "),horario());System.out.println("Mentoria CONFIRMADA.");}}break;case 7:if(listarMentorias(u)){int id=numero("ID mentoria (0 cancela): ");if(id!=0){int d=numero("1 - Confirmar | 2 - Recusar | 3 - Propor novo horario: ");sistema.responderMentoria(u,sistema.mentoria(id),d,d==3?horario():null);System.out.println("Mentoria: "+sistema.mentoria(id).getStatus());}}break;default:System.out.println("Opcao invalida.");}}catch(IllegalArgumentException e){erro(e);}}}
    private void aluno(Usuario u){while(true){System.out.println("\n--- ALUNO: "+u.getNome()+" ---\n1 - Consultar atividades\n2 - Enviar atividade\n3 - Minhas equipes\n4 - Criar equipe\n5 - Editar equipe (lider)\n6 - Convidar aluno (lider)\n7 - Responder convites\n8 - Criar projeto (lider)\n9 - Meus projetos\n10 - Solicitar mentoria (lider)\n11 - Consultar mentorias\n12 - Responder reagendamento (lider)\n0 - Trocar conta");try{switch(numero("Opcao: ")){case 0:return;case 1:listarAtividades(u);break;case 2:if(listarAtividades(u)){int id=numero("ID atividade (0 cancela): ");if(id!=0){sistema.entregar(u,sistema.atividade(id),texto("Resposta: "));System.out.println("Entrega registrada.");}}break;case 3:listarEquipes(sistema.equipesDe(u));break;case 4:{Equipe e=sistema.criarEquipe(u,texto("Nome: "),texto("Descricao: "),linha("Foto (referencia opcional): "));System.out.println("Equipe criada. ID: "+e.getId());break;}case 5:{Equipe e=selecionarEquipe(u);if(e!=null){sistema.editarEquipe(u,e,texto("Novo nome: "),texto("Nova descricao: "),linha("Nova foto (referencia opcional): "));System.out.println("Equipe atualizada.");}break;}case 6:{Equipe e=selecionarEquipe(u);if(e!=null){sistema.getUsuarios().stream().filter(a->!a.isProfessor()&&a!=u).forEach(System.out::println);int id=numero("ID aluno (0 cancela): ");if(id!=0){sistema.convidar(u,e,sistema.usuario(id));System.out.println("Convite enviado.");}}break;}case 7:if(listarEquipes(sistema.convitesDe(u))){int id=numero("ID equipe (0 cancela): ");if(id!=0){boolean aceitar=simNao();sistema.responderConvite(u,sistema.equipe(id),aceitar);System.out.println(aceitar?"Convite aceito.":"Convite recusado.");}}break;case 8:{Equipe e=selecionarEquipe(u);if(e!=null){Projeto p=sistema.criarProjeto(u,e,texto("Nome do projeto: "),texto("Descricao: "));System.out.println("Projeto criado. ID: "+p.getId());}break;}case 9:listarProjetos(sistema.projetosDe(u));break;case 10:if(listarProjetos(sistema.projetosDe(u))){int id=numero("ID projeto (0 cancela): ");if(id!=0){sistema.solicitarMentoria(u,sistema.projeto(id),texto("Assunto: "),horario());System.out.println("Solicitacao PENDENTE.");}}break;case 11:listarMentorias(u);break;case 12:if(listarMentorias(u)){int id=numero("ID mentoria (0 cancela): ");if(id!=0){sistema.responderReagendamento(u,sistema.mentoria(id),simNao());System.out.println("Mentoria: "+sistema.mentoria(id).getStatus());}}break;default:System.out.println("Opcao invalida.");}}catch(IllegalArgumentException e){erro(e);}}}
    private Equipe selecionarEquipe(Usuario u){if(!listarEquipes(sistema.equipesDe(u)))return null;int id=numero("ID equipe (0 cancela): ");return id==0?null:sistema.equipe(id);}
    private boolean listarAtividades(Usuario u){List<Atividade> lista=sistema.atividadesDe(u);if(lista.isEmpty()){System.out.println("Nenhuma atividade.");return false;}int feitas=0;for(Atividade a:lista){System.out.println("\nID: "+a.getId()+" | "+a.getTitulo()+" | "+a.getMateria()+" | Prazo: "+a.getPrazo().format(DATA));System.out.println("Descricao: "+a.getDescricao()+" | Professor: "+a.getProfessor().getNome());if(u.isProfessor()){List<Entrega> entregas=sistema.consultarEntregas(u,a);System.out.println("Entregas: "+entregas.size());for(Entrega e:entregas)System.out.println(e.getAluno().getNome()+" | "+e.getData().format(DATA)+" | "+e.getResposta());}else{System.out.println("Status: "+a.status(u,LocalDate.now()));if(a.entregaDe(u)!=null)feitas++;}}if(!u.isProfessor())System.out.println("Total: "+lista.size()+" | Feitas: "+feitas+" | Nao feitas: "+(lista.size()-feitas));return true;}
    private boolean listarEquipes(List<Equipe> lista){if(lista.isEmpty()){System.out.println("Nenhuma equipe ou convite.");return false;}for(Equipe e:lista){System.out.println("ID: "+e.getId()+" | "+e.getNome()+" | Lider: "+e.getLider().getNome());System.out.println("Descricao: "+e.getDescricao()+" | Foto: "+(e.getFoto().isEmpty()?"Nao definida":e.getFoto()));System.out.print("Membros: ");for(Usuario u:e.getMembros())System.out.print(u.getNome()+"; ");System.out.println();}return true;}
    private boolean listarProjetos(List<Projeto> lista){if(lista.isEmpty()){System.out.println("Nenhum projeto.");return false;}for(Projeto p:lista)System.out.println("ID: "+p.getId()+" | "+p.getNome()+" | Equipe: "+p.getEquipe().getNome()+" | Mentor: "+(p.getMentor()==null?"A definir":p.getMentor().getNome())+"\nDescricao: "+p.getDescricao());return true;}
    private boolean listarMentorias(Usuario u){List<Mentoria> lista=sistema.mentoriasDe(u);if(lista.isEmpty()){System.out.println("Nenhuma mentoria.");return false;}for(Mentoria m:lista)System.out.println("ID: "+m.getId()+" | "+m.getProjeto().getNome()+" | "+m.getProfessor().getNome()+" | "+m.getHorario().format(HORARIO)+" | "+m.getStatus()+"\nAssunto: "+m.getAssunto());return true;}
    private String linha(String prompt){System.out.print(prompt);return entrada.nextLine().trim();}
    private String texto(String prompt){while(true){String s=linha(prompt);if(!s.isEmpty())return s;System.out.println("Campo obrigatorio.");}}
    private int numero(String prompt){while(true){try{return Integer.parseInt(linha(prompt));}catch(NumberFormatException e){System.out.println("Digite um numero inteiro.");}}}
    private boolean simNao(){while(true){int n=numero("1 - Aceitar | 2 - Recusar: ");if(n==1||n==2)return n==1;System.out.println("Opcao invalida.");}}
    private LocalDate data(){while(true){try{return LocalDate.parse(linha("Prazo (dd/MM/aaaa): "),DATA);}catch(DateTimeParseException e){System.out.println("Data invalida.");}}}
    private LocalDateTime horario(){while(true){try{return LocalDateTime.parse(linha("Data e hora (dd/MM/aaaa HH:mm): "),HORARIO);}catch(DateTimeParseException e){System.out.println("Data ou horario invalido.");}}}
    private void erro(IllegalArgumentException e){System.out.println("Operacao recusada: "+e.getMessage());}
}
